import { merge } from 'es-toolkit';
import { startCase, fromPairs } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function applyPatch(base: Config, patch: Config): Config {
  return merge(base, patch);
}

export function toTitle(key: string): string {
  return startCase(key);
}

export function toLookup(pairs: [string, number][]): Record<string, number> {
  return fromPairs(pairs);
}
EOF
npm run size -- out/module.ts 2>&1 | tail -2
sed -e "s/import { merge } from 'es-toolkit';/import { merge, zipObject } from 'es-toolkit';/" -e "s/startCase, fromPairs/startCase/" -e "s/return fromPairs(pairs);/return zipObject(pairs.map(p => p[0]), pairs.map(p => p[1]));/" out/module.ts > out/alt.ts
npm run size -- out/alt.ts 2>&1 | tail -1
sed -e "s/import { merge } from 'es-toolkit';/import { merge } from 'es-toolkit\/compat';/" out/module.ts > out/alt2.ts; npm run size -- out/alt2.ts 2>&1 | tail -1
npx tsc --noEmit -p . 2>&1 | head

